fn render_view(view: &FactoryAiScoredView) -> String {
    let mut output = String::from("{\"schema\":");
    push_string(&mut output, view.schema);
    output.push_str(",\"mode\":");
    push_string(&mut output, view.mode);
    write!(
        output,
        ",\"active\":{{\"aiBattler\":{},\"targetBattler\":{}}}",
        view.active.ai_battler, view.active.target_battler
    )
    .unwrap();
    output.push_str(",\"factory\":{\"levelMode\":");
    write!(output, "{}", view.factory.level_mode).unwrap();
    output.push_str(",\"battleMode\":");
    write!(output, "{}", view.factory.battle_mode).unwrap();
    output.push_str(",\"factoryWinStreak\":");
    push_number(&mut output, view.factory.factory_win_streak);
    output.push_str(",\"trainerOpponentId\":");
    push_number(&mut output, view.factory.trainer_opponent_id);
    output.push_str("},\"moves\":");
    push_number_array(&mut output, &view.moves);
    output.push_str(",\"attacker\":");
    output.push_str(&render_attacker(&view.attacker));
    output.push_str(",\"target\":");
    output.push_str(&render_target(&view.target));
    output.push('}');
    output
}

fn side_name(side: FactoryAiDecisionSide) -> &'static str {
    match side {
        FactoryAiDecisionSide::Player => "player",
        FactoryAiDecisionSide::Trainer => "trainer",
    }
}

fn push_move_decision(output: &mut String, decision: FactoryAiMoveDecision) {
    write!(
        output,
        "{{\"kind\":\"use-move\",\"moveSlot\":{},\"targetBattler\":{}}}",
        decision.move_slot.index(),
        decision.target_battler
    )
    .unwrap();
}

fn push_move_submission(output: &mut String, submission: FactoryAiDecisionSubmission) {
    write!(
        output,
        "{{\"requestId\":{},\"side\":\"{}\",\"decision\":",
        submission.request_id,
        side_name(submission.side)
    )
    .unwrap();
    push_move_decision(output, submission.decision);
    output.push('}');
}

fn push_history(output: &mut String, history: &FactoryAiBattleHistory) {
    output.push_str("{\"usedMoves\":[");
    for (index, moves) in history.used_moves.iter().enumerate() {
        if index != 0 {
            output.push(',');
        }
        push_number_array(output, moves);
    }
    output.push_str("],\"knownAbilities\":[");
    for (index, ability) in history.known_abilities.iter().enumerate() {
        if index != 0 {
            output.push(',');
        }
        if let Some(ability) = ability {
            push_string(output, ability);
        } else {
            output.push_str("null");
        }
    }
    output.push_str("],\"knownItemEffects\":");
    push_number_array(output, &history.known_item_effects);
    output.push_str(",\"partyIndexes\":");
    push_number_array(output, &history.party_indexes);
    output.push('}');
}

