fn push_option_u8(output: &mut String, value: Option<u8>) {
    if let Some(value) = value {
        write!(output, "{value}").unwrap();
    } else {
        output.push_str("null");
    }
}

fn push_switch_policy(output: &mut String, result: &FactoryAiSwitchPolicyResult) {
    write!(
        output,
        "{{\"schema\":\"{}\",\"choice\":{{\"kind\":\"{}\"",
        result.schema,
        choice_name(result.choice)
    )
    .unwrap();
    if let FactoryAiSwitchChoice::Chosen { party_index } = result.choice {
        write!(output, ",\"partyIndex\":{party_index}").unwrap();
    }
    output.push_str("},\"selectedPartyIndex\":");
    push_option_u8(output, result.selected_party_index);
    output.push_str(",\"rng\":");
    push_rng(output, result.rng);
    output.push_str(",\"draws\":[");
    for (index, draw) in result.draws.iter().enumerate() {
        if index != 0 {
            output.push(',');
        }
        write!(
            output,
            "{{\"ordinal\":{},\"reason\":\"{}\",\"kind\":\"{}\",\"before\":",
            draw.ordinal,
            draw.reason,
            draw_kind_name(draw.kind)
        )
        .unwrap();
        push_rng(output, draw.before);
        output.push_str(",\"after\":");
        push_rng(output, draw.after);
        write!(
            output,
            ",\"rawRngValue\":{},\"randomValue\":{},\"modulus\":{},\"remainder\":{},\"succeeded\":{},\"partyIndex\":",
            draw.raw_rng_value,
            draw.random_value,
            draw.modulus,
            draw.remainder,
            draw.succeeded
        )
        .unwrap();
        push_option_u8(output, draw.party_index);
        output.push_str(",\"moveSlot\":");
        push_option_u8(output, draw.move_slot);
        output.push('}');
    }
    output.push_str("],\"branches\":[");
    for (index, branch) in result.branches.iter().enumerate() {
        if index != 0 {
            output.push(',');
        }
        write!(
            output,
            "{{\"ordinal\":{},\"branch\":\"{}\",\"outcome\":\"{}\",\"partyIndex\":",
            branch.ordinal,
            switch_branch_name(branch.branch),
            switch_outcome_name(branch.outcome)
        )
        .unwrap();
        push_option_u8(output, branch.party_index);
        output.push('}');
    }
    output.push_str("]}");
}

fn policy_branch_name(branch: FactoryAiPolicyBranchId) -> &'static str {
    match branch {
        FactoryAiPolicyBranchId::Tent => "tent",
        FactoryAiPolicyBranchId::FrontierBrain => "frontierBrain",
        FactoryAiPolicyBranchId::ChallengeBelow2 => "challengeBelow2",
        FactoryAiPolicyBranchId::ChallengeBelow4 => "challengeBelow4",
        FactoryAiPolicyBranchId::ChallengeAtLeast4 => "challengeAtLeast4",
    }
}

fn policy_branch_condition(branch: FactoryAiPolicyBranchId) -> &'static str {
    match branch {
        FactoryAiPolicyBranchId::Tent => "lvlMode == FRONTIER_LVL_TENT",
        FactoryAiPolicyBranchId::FrontierBrain => {
            "gTrainerBattleOpponent_A == TRAINER_FRONTIER_BRAIN"
        }
        FactoryAiPolicyBranchId::ChallengeBelow2 => "challengeNum < 2",
        FactoryAiPolicyBranchId::ChallengeBelow4 => "challengeNum < 4",
        FactoryAiPolicyBranchId::ChallengeAtLeast4 => "else",
    }
}

fn push_policy_flags(output: &mut String, branch: FactoryAiPolicyBranchId) {
    output.push('[');
    let flags: &[&str] = match branch {
        FactoryAiPolicyBranchId::Tent | FactoryAiPolicyBranchId::ChallengeBelow2 => &[],
        FactoryAiPolicyBranchId::ChallengeBelow4 => &["AI_SCRIPT_CHECK_BAD_MOVE"],
        FactoryAiPolicyBranchId::FrontierBrain | FactoryAiPolicyBranchId::ChallengeAtLeast4 => &[
            "AI_SCRIPT_CHECK_BAD_MOVE",
            "AI_SCRIPT_TRY_TO_FAINT",
            "AI_SCRIPT_CHECK_VIABILITY",
        ],
    };
    for (index, flag) in flags.iter().enumerate() {
        if index != 0 {
            output.push(',');
        }
        push_string(output, flag);
    }
    output.push(']');
}

fn push_mask_selection(output: &mut String, selection: FactoryAiMaskSelection) {
    let receipt = selection.receipt;
    output.push_str("{\"schema\":\"factory-ai-mask-selection/v1\",\"inputs\":{\"levelMode\":");
    write!(output, "{}", receipt.inputs.level_mode).unwrap();
    output.push_str(",\"battleMode\":");
    write!(output, "{}", receipt.inputs.battle_mode).unwrap();
    output.push_str(",\"factoryWinStreak\":");
    write!(output, "{}", receipt.inputs.factory_win_streak).unwrap();
    output.push_str(",\"trainerOpponentId\":");
    write!(output, "{}", receipt.inputs.trainer_opponent_id).unwrap();
    output.push_str(",\"isFrontierBrain\":");
    push_bool(output, receipt.is_frontier_brain);
    output.push_str("},\"frontierStagesPerChallenge\":");
    write!(output, "{}", receipt.frontier_stages_per_challenge).unwrap();
    output.push_str(",\"challengeNumber\":");
    if let Some(challenge_number) = receipt.challenge_number {
        write!(output, "{challenge_number}").unwrap();
    } else {
        output.push_str("null");
    }
    output.push_str(",\"evaluations\":[");
    for (index, evaluation) in receipt.evaluations[..usize::from(receipt.evaluation_count)]
        .iter()
        .enumerate()
    {
        if index != 0 {
            output.push(',');
        }
        write!(
            output,
            "{{\"order\":{},\"id\":\"{}\",\"matched\":{}}}",
            evaluation.branch as u8,
            policy_branch_name(evaluation.branch),
            evaluation.matched
        )
        .unwrap();
    }
    write!(
        output,
        "],\"branch\":{{\"order\":{},\"id\":\"{}\",\"condition\":\"{}\",\"flags\":",
        receipt.branch as u8,
        policy_branch_name(receipt.branch),
        policy_branch_condition(receipt.branch)
    )
    .unwrap();
    push_policy_flags(output, receipt.branch);
    write!(output, ",\"mask\":{}}}}}", receipt.mask).unwrap();
}

fn scoring_script_name(script: FactoryAiScoringScript) -> &'static str {
    match script {
        FactoryAiScoringScript::CheckBadMove => "check-bad-move",
        FactoryAiScoringScript::TryToFaint => "try-to-faint",
        FactoryAiScoringScript::CheckViability => "check-viability",
    }
}

fn push_setup_draw(
    output: &mut String,
    draw: factory_core::factory_ai_decision_policy::FactoryAiSetupDraw,
) {
    write!(
        output,
        "{{\"ordinal\":{},\"reason\":\"setup-simulated-rng-slot-{}\",\"before\":",
        draw.ordinal,
        draw.move_slot.index()
    )
    .unwrap();
    push_rng(output, draw.before);
    output.push_str(",\"after\":");
    push_rng(output, draw.after);
    write!(
        output,
        ",\"rawRngValue\":{},\"randomValue\":{},\"kind\":\"setup-simulated-rng\",\"moveSlot\":{},\"simulatedRng\":{}}}",
        draw.raw_rng_value,
        draw.random_value,
        draw.move_slot.index(),
        draw.simulated_rng
    )
    .unwrap();
}

fn push_tie_draw(
    output: &mut String,
    draw: factory_core::factory_ai_decision_policy::FactoryAiTieDraw,
) {
    write!(
        output,
        "{{\"ordinal\":{},\"reason\":\"best-move-tie-selection\",\"before\":",
        draw.ordinal
    )
    .unwrap();
    push_rng(output, draw.before);
    output.push_str(",\"after\":");
    push_rng(output, draw.after);
    write!(
        output,
        ",\"rawRngValue\":{},\"randomValue\":{},\"kind\":\"best-move-tie\"}}",
        draw.raw_rng_value, draw.random_value
    )
    .unwrap();
}

fn push_mask_zero_draw(output: &mut String, draw: FactoryAiRngDraw) {
    match draw {
        FactoryAiRngDraw::SetupSimulatedRng(draw) => push_setup_draw(output, draw),
        FactoryAiRngDraw::BestMoveTie(draw) => push_tie_draw(output, draw),
    }
}

fn check_bad_move_reason(site: CheckBadMoveDrawSite) -> &'static str {
    match site {
        CheckBadMoveDrawSite::NegatesType => "negates-type",
        CheckBadMoveDrawSite::Soundproof => "soundproof",
        value => panic!(
            "the M8i corpus intentionally stages only the source preamble draw sites, got {value:?}"
        ),
    }
}

fn push_scored_draw(output: &mut String, draw: FactoryAiScoredDraw) {
    match draw {
        FactoryAiScoredDraw::SetupSimulatedRng(draw) => push_setup_draw(output, draw),
        FactoryAiScoredDraw::CheckBadMove { move_slot, draw } => {
            let ability =
                factory_core::gen_tables::ability_name_by_id(f64::from(draw.guessed_ability))
                    .expect("native check-bad-move draw carries a generated ability id");
            write!(
                output,
                "{{\"ordinal\":{},\"reason\":\"slot-{}-check-bad-move-{}\",\"kind\":\"get-ability\",\"before\":",
                draw.ordinal,
                move_slot.index(),
                check_bad_move_reason(draw.site)
            )
            .unwrap();
            push_rng(output, draw.before);
            output.push_str(",\"after\":");
            push_rng(output, draw.after);
            write!(
                output,
                ",\"rawRngValue\":{},\"randomValue\":{},\"guessedAbility\":\"{}\",\"phase\":\"check-bad-move\",\"moveSlot\":{}}}",
                draw.raw_rng_value,
                draw.random_value,
                ability,
                move_slot.index()
            )
            .unwrap();
        }
        FactoryAiScoredDraw::BestMoveTie(draw) => push_tie_draw(output, draw),
        FactoryAiScoredDraw::TurnStartRandomNumber(_)
        | FactoryAiScoredDraw::TryToFaint { .. }
        | FactoryAiScoredDraw::CheckViability { .. } => panic!(
            "the M8i staged corpus has no fresh boundary, try-to-faint, or viability draw receipts"
        ),
    }
}

fn push_mask_zero_slot_score(output: &mut String, score: FactoryAiSlotScore) {
    write!(
        output,
        "{{\"moveSlot\":{},\"moveId\":{},\"legal\":{},\"initialScore\":{},\"finalScore\":{}}}",
        score.move_slot.index(),
        score.move_id,
        score.legal,
        score.initial_score,
        score.final_score
    )
    .unwrap();
}

fn push_option_i32(output: &mut String, value: Option<i32>) {
    if let Some(value) = value {
        write!(output, "{value}").unwrap();
    } else {
        output.push_str("null");
    }
}

fn push_scored_slot_score(
    output: &mut String,
    score: factory_core::factory_ai_decision_policy::FactoryAiScoredSlot,
) {
    write!(
        output,
        "{{\"moveSlot\":{},\"moveId\":{},\"legal\":{},\"initialScore\":{},\"checkBadMoveDelta\":",
        score.move_slot.index(),
        score.move_id,
        score.legal,
        score.initial_score
    )
    .unwrap();
    push_option_i32(output, score.check_bad_move_delta);
    output.push_str(",\"tryToFaintDelta\":");
    push_option_i32(output, score.try_to_faint_delta);
    output.push_str(",\"checkViabilityDelta\":");
    push_option_i32(output, score.check_viability_delta);
    write!(output, ",\"finalScore\":{}}}", score.final_score).unwrap();
}

fn push_best_move_slots(output: &mut String, slots: &[FactoryAiMoveSlot], count: u8) {
    output.push('[');
    for (index, slot) in slots[..usize::from(count)].iter().enumerate() {
        if index != 0 {
            output.push(',');
        }
        write!(output, "{}", slot.index()).unwrap();
    }
    output.push(']');
}

fn push_tie(output: &mut String, modulus: u8, index: u8, decision: FactoryAiMoveDecision) {
    write!(
        output,
        "{{\"modulus\":{modulus},\"index\":{index},\"chosenDecision\":"
    )
    .unwrap();
    push_move_decision(output, decision);
    output.push('}');
}

fn push_mask_zero_trace(output: &mut String, trace: FactoryAiMaskZeroTrace) {
    write!(
        output,
        "{{\"schema\":\"factory-ai-trace/v1\",\"phase\":\"choose-move\",\"mask\":{},\"maskSelection\":",
        trace.mask
    )
    .unwrap();
    push_mask_selection(output, trace.mask_selection);
    output.push_str(",\"executedScoringScripts\":[],\"draws\":[");
    for (index, draw) in trace.draws.iter().enumerate() {
        if index != 0 {
            output.push(',');
        }
        push_mask_zero_draw(output, *draw);
    }
    output.push_str("],\"slotScores\":[");
    for (index, score) in trace.slot_scores.iter().enumerate() {
        if index != 0 {
            output.push(',');
        }
        push_mask_zero_slot_score(output, *score);
    }
    output.push_str("],\"bestMoveSlots\":");
    push_best_move_slots(output, &trace.best_move_slots, trace.best_move_slot_count);
    output.push_str(",\"tie\":");
    push_tie(
        output,
        trace.tie_modulus,
        trace.tie_index,
        trace.chosen_decision,
    );
    output.push('}');
}

fn turn_start_owner_name(owner: FactoryAiTurnStartOwner) -> &'static str {
    match owner {
        FactoryAiTurnStartOwner::Decision => "decision",
        FactoryAiTurnStartOwner::BattleTurnBoundary => "battle-turn-boundary",
        FactoryAiTurnStartOwner::LegacyPostBoundary => "legacy-post-boundary",
    }
}

fn push_scored_trace(output: &mut String, trace: FactoryAiScoredTrace) {
    write!(
        output,
        "{{\"schema\":\"factory-ai-trace/v1\",\"phase\":\"choose-move\",\"mask\":{},\"maskSelection\":",
        trace.mask
    )
    .unwrap();
    push_mask_selection(output, trace.mask_selection);
    output.push_str(",\"executedScoringScripts\":[");
    for (index, script) in trace.executed_scoring_scripts
        [..usize::from(trace.executed_scoring_script_count)]
        .iter()
        .enumerate()
    {
        if index != 0 {
            output.push(',');
        }
        push_string(
            output,
            scoring_script_name(script.expect("score trace only counts populated scripts")),
        );
    }
    output.push_str("],\"turnStartRandomNumber\":{\"owner\":");
    push_string(
        output,
        turn_start_owner_name(trace.turn_start_random_number.owner),
    );
    output.push_str(",\"value\":");
    if let Some(value) = trace.turn_start_random_number.value {
        write!(output, "{value}").unwrap();
    } else {
        output.push_str("null");
    }
    output.push_str("},\"draws\":[");
    for (index, draw) in trace.draws[..usize::from(trace.draw_count)]
        .iter()
        .enumerate()
    {
        if index != 0 {
            output.push(',');
        }
        push_scored_draw(
            output,
            draw.expect("score trace only counts populated draw receipts"),
        );
    }
    output.push_str("],\"slotScores\":[");
    for (index, score) in trace.slot_scores.iter().enumerate() {
        if index != 0 {
            output.push(',');
        }
        push_scored_slot_score(output, *score);
    }
    output.push_str("],\"bestMoveSlots\":");
    push_best_move_slots(output, &trace.best_move_slots, trace.best_move_slot_count);
    output.push_str(",\"tie\":");
    push_tie(
        output,
        trace.tie_modulus,
        trace.tie_index,
        trace.chosen_decision,
    );
    output.push('}');
}

fn push_move_common(
    output: &mut String,
    history: &FactoryAiBattleHistory,
    view: &FactoryAiScoredView,
    switch_policy: &FactoryAiSwitchPolicyResult,
) {
    output.push_str(",\"history\":");
    push_history(output, history);
    output.push_str(",\"view\":");
    output.push_str(&render_view(view));
    output.push_str(",\"switchPolicy\":");
    push_switch_policy(output, switch_policy);
    output.push_str(",\"actionGate\":{\"item\":\"frontier-trainer-items-source-unreachable\"}");
}

fn render_plan(result: &FactoryAiLivePlannerResult) -> String {
    let mut output = String::new();
    match result {
        FactoryAiLivePlannerResult::Move(result) => {
            output.push_str("{\"phase\":\"move\",\"submission\":");
            push_move_submission(&mut output, result.submission);
            output.push_str(",\"rng\":");
            push_rng(&mut output, result.rng);
            output.push_str(",\"trace\":");
            match result.trace {
                FactoryAiLivePlannerMoveTrace::MaskZero(trace) => {
                    push_mask_zero_trace(&mut output, trace);
                }
                FactoryAiLivePlannerMoveTrace::Scored(trace) => {
                    push_scored_trace(&mut output, trace);
                }
            }
            push_move_common(
                &mut output,
                &result.history,
                &result.view,
                &result.switch_policy,
            );
        }
        FactoryAiLivePlannerResult::Switch(result) => {
            write!(
                output,
                "{{\"phase\":\"switch\",\"submission\":{{\"requestId\":{},\"side\":\"{}\",\"decision\":{{\"kind\":\"switch\",\"partyIndex\":{}}}}},\"rng\":",
                result.submission.request_id,
                side_name(result.submission.side),
                result.submission.party_index
            )
            .unwrap();
            push_rng(&mut output, result.rng);
            push_move_common(
                &mut output,
                &result.history,
                &result.view,
                &result.switch_policy,
            );
        }
    }
    output.push('}');
    output
}

#[test]
fn complete_pure_plans_and_errors_match_canonical_typescript() {
    assert_eq!(FACTORY_AI_LIVE_PLANNER_CASES.len(), 12);
    for (index, case) in FACTORY_AI_LIVE_PLANNER_CASES.iter().enumerate() {
        match execute_case(case) {
            Ok(result) => {
                assert!(
                    case.expected_error.is_none(),
                    "case {index} ({}) unexpectedly succeeded",
                    case.label
                );
                assert_eq!(
                    Some(result.as_str()),
                    case.expected_json,
                    "case {index} ({})",
                    case.label
                );
            }
            Err(error) => {
                assert!(
                    case.expected_json.is_none(),
                    "case {index} ({}) unexpectedly failed",
                    case.label
                );
                assert_eq!(
                    Some(error.as_str()),
                    case.expected_error,
                    "case {index} ({})",
                    case.label
                );
            }
        }
    }
}

#[test]
fn category_census_is_ratchet_pinned() {
    let mut observed = BTreeMap::new();
    for case in FACTORY_AI_LIVE_PLANNER_CASES {
        *observed.entry(case.category).or_insert(0usize) += 1;
    }
    let expected = FACTORY_AI_LIVE_PLANNER_VECTOR_CATEGORY_COUNTS
        .iter()
        .copied()
        .collect::<BTreeMap<_, _>>();
    assert_eq!(observed, expected);
    assert_eq!(FACTORY_AI_LIVE_PLANNER_CASES.len(), 12);
}
